DEFAULT = DEFAULT_12X6

def wrap_text(text, wrap_or_size=None, font=DEFAULT,  
              spacing=0, padding=0):
    if isinstance(wrap_or_size, (tuple, list, _torch.Size, _torch.Tensor)):
        size = wrap_or_size
        wrap = None
    else:
        size = None
        wrap = wrap_or_size
    if not isinstance(spacing, (list, tuple)):
        spacing = [spacing] * 2
    if not isinstance(padding, (list, tuple)):
        padding = [padding] * 4
    if len(padding) == 2:
        padding = [padding[0],padding[0],padding[1],padding[1]]
    assert len(padding) == 4

    if size is not None:
        width_of_char = len(DEFAULT[" "][0]) + spacing[0]
        width_available = size[0] - (padding[0] + padding[1]) + spacing[0] 
        max_chars_per_line = width_available // width_of_char
    elif wrap is not None:
        max_chars_per_line = wrap
    else:
        max_chars_per_line = 1<<32
    
    lines = text.strip().split("\n")
    i = 0
    while i < len(lines):
        line = lines[i] 
        if len(line) > max_chars_per_line:
            lines.insert(i+1,"")
        while len(line) > max_chars_per_line:
            line, word = line.rsplit(" ", 1)
            word = word.strip()
            if len(word) == 0: continue
            if len(lines[i+1]) == 0: lines[i+1] = word
            else: lines[i+1] = word + " " + lines[i+1]
        lines[i] = line
        i += 1
    return lines

def render_text_to(dst, text, font=DEFAULT, spacing=0, padding=1, 
                   device="cpu", **kwargs):
    
    if not isinstance(spacing, (list, tuple)):
        spacing = [spacing] * 2
    if not isinstance(padding, (list, tuple)):
        padding = [padding] * 4
    if len(padding) == 2:
        padding = [padding[0],padding[0],padding[1],padding[1]]
    assert len(padding) == 4

    lines = wrap_text(text, dst.shape[-2:], spacing=spacing, padding=padding)
    ...
    assert False
    
def render_text(text, font=DEFAULT, spacing=0, padding=1, wrap=80, 
                device="cpu",colorspace="palette", **kwargs):
    if not isinstance(spacing, (list, tuple)):
        spacing = [spacing] * 2
    if not isinstance(padding, (list, tuple)):
        padding = [padding] * 4
    if len(padding) == 2:
        padding = [padding[0],padding[0],padding[1],padding[1]]
    assert len(padding) == 4

    lines = text.split("\n")
    rlines = []
    for line in lines:
        while len(line) > wrap:
            rlines.append(line[:wrap])
            line = line[wrap:]
        if len(line):
            rlines.append(line)
    lines = rlines
    max_length = max(len(line) for line in lines)
    rs = []
    for j,line in enumerate(lines):
        r = []
        for i,c in enumerate(line):
            if c not in font: continue
            c = _torch.tensor(font[c], dtype=_torch.long, device=device)
            c = _F.pad(c, (0, spacing[1] if i < len(line)-1 else 0, 
                          0, spacing[0] if j < len(lines)-1 else 0),
                       "constant", TRANSPARENT)
            r.append(c)
        if len(r):
            rs.append(_Fx.padcat(r, -1))
    
    
    if len(rs):
        rs = _Fx.padcat(rs, -2, "constant", TRANSPARENT)
    else:
        rs = torch.zeros(1,1,device=device)
    rs = _F.pad(rs, padding, "constant", TRANSPARENT)
        
    if colorspace == "rgb":
        rs = palette_to_rgb(rs[None])
        return rs
    else:
        return rs[None].float()

